 }

 public static function handle(\PDO $p,?array $user,string $path):never {
  if(!$user)Support::redirect('/login');$actor=(int)$user['id'];$message='';$h='';
  try {
   if($_SERVER['REQUEST_METHOD']==='POST'){
    Support::checkCsrf();$action=Support::post('action',40);
    if($path==='/registration-contact'&&$action==='contact'){RegistrationMaster::contactSave($p,$actor,(int)$user['staff_identity_id'],$_POST);$message='Contact & privacy disimpan.';}
    elseif($path==='/registration-admin'&&$action==='review'){SmartRegistration::review($p,$actor,Core::id($_POST['id']??''),Support::post('decision',30),Support::post('reason',500));$message='Keputusan direkodkan.';}
    elseif($path==='/registration-admin'&&$action==='import_report'){Authorization::require($p,$actor,'core.master.manage');$report=$_SESSION['master_import_report']??null;if(!is_array($report)||$report['actor']!==$actor||$report['expires']<time())throw new \RuntimeException('Report tamat/tidak tersedia.');header('Content-Type: application/json');header('Content-Disposition: attachment; filename=master-import-report.json');header('Cache-Control: no-store');echo json_encode($report['rows'],JSON_PRETTY_PRINT|JSON_THROW_ON_ERROR);exit;}
    elseif($path==='/registration-admin'&&$action==='directory_contact'){RegistrationMaster::directorySave($p,$actor,Core::id($_POST['id']??''),$_POST);$message='Contact organisasi disimpan; pengesahan sumber diperlukan.';}
    elseif($path==='/registration-admin'&&$action==='source_import'){$selected=$_POST['selected']??[];if(!is_array($selected)||count($selected)>100)throw new \InvalidArgumentException('Pilihan source tidak sah.');$mapping=[];$codes=['LOCAL_STATE_KELANTAN'];foreach(MasterSourceImport::candidates()['organisations'] as $candidate)if($candidate['type']==='pkd')$codes[]=$candidate['local_code'];foreach($codes as $code){$value=$_POST['parent_'.$code]??'';if($value!=='')$mapping[$code]=Core::id($value);}foreach($selected as $code){if(!is_string($code)||!preg_match('/\ALOCAL_[A-Z0-9_]+\z/',$code))throw new \InvalidArgumentException('Kod source tidak sah.');$value=$_POST['record_parent_'.$code]??'';if($value!=='')$mapping[$code]=Core::id($value);}$report=MasterSourceImport::apply($p,$actor,$selected,Support::post('reason',500),$mapping);$_SESSION['master_import_report']=['actor'=>$actor,'expires'=>time()+3600,'rows'=>$report];$message=count($report).' rekod diproses; download result report tersedia. Rekod sedia ada tidak dioverwrite.';}
    elseif($path==='/registration-admin'&&in_array($action,['directory_verify','professional_catalog_import','professional_review','contact_review','professional_catalog','facility_review','unit_save','official_name','specialist_catalog_activate'],true)){self::addendaAction($p,$actor,$action,$_POST);$message='Semakan direkodkan.';}
