    elseif(in_array($path,['/registration-admin','/registration-contact'],true)&&$action==='missing_org'){RegistrationMaster::missingOrganisation($p,$actor,Core::id($_POST['parent_id']??''),Support::post('name',190));$message='Permohonan organisasi direkodkan.';}
    elseif($path==='/registration-admin'&&$action==='org_review'){RegistrationMaster::reviewOrganisation($p,$actor,Core::id($_POST['id']??''),Support::post('decision',30),Support::post('reason',500));$message='Semakan direkodkan; penciptaan organisasi menggunakan pengurusan organisasi sedia ada.';}
    else throw new \RuntimeException('Tindakan tidak sah.');
   }
   if($path==='/registration-contact'){if(isset($_GET['id'])&&(int)Core::id($_GET['id'])!==(int)$user['staff_identity_id']){$contact=RegistrationMaster::contact($p,$actor,Core::id($_GET['id']));$h='<section class="card"><h2>Contact yang dibenarkan</h2>';if(!$contact)$h.='<p>Tiada contact dikongsi.</p>';if($contact['alternative_phone']??null)$h.='<p><a href="tel:'.Support::escape($contact['alternative_phone']).'">Telefon</a></p>';if($contact['whatsapp_url']??null)$h.='<p><a href="'.Support::escape($contact['whatsapp_url']).'" rel="noopener noreferrer">WhatsApp</a></p>';Ui::layout('Contact Privacy',$h.'</section>','<a href="/dashboard">Dashboard</a>');}$saved=Database::query($p,'SELECT * FROM staff_contact_preferences WHERE staff_identity_id=?',[$user['staff_identity_id']])->fetch()?:[];$h='<section class="card"><h2>Hubungan & privasi saya</h2><p>Nombor WhatsApp hanya boleh dilihat dalam skop yang dibenarkan selepas persetujuan anda. Jangan kongsi maklumat pesakit atau dokumen sulit.</p>'.Support::form('contact',Support::fields(['alternative_phone'=>['Telefon alternatif','tel',$saved['alternative_phone']??''],'whatsapp_number'=>['Nombor WhatsApp','tel',$saved['whatsapp_number']??'']]).'<label><input type="checkbox" name="whatsapp_consent" value="1"'.(!empty($saved['whatsapp_consent'])?' checked':'').'>Saya bersetuju berkongsi pautan WhatsApp dalam organisasi</label><label>Visibility<select name="visibility"><option value="private">Private</option><option value="organisation"'.(($saved['visibility']??'private')==='organisation'?' selected':'').'>Organisasi yang dibenarkan</option></select></label>','Simpan').'<h2>Organisasi belum disenaraikan</h2>'.Support::form('missing_org',self::select('parent_id','Induk organisasi',Database::query($p,'SELECT o.id,o.name FROM organisations o JOIN organisation_hierarchy h ON h.ancestor_id=o.id WHERE h.descendant_id=(SELECT organisation_id FROM staff_profiles WHERE staff_identity_id=?) ORDER BY o.name',[$user['staff_identity_id']])->f