  $rows=Database::query($p,'SELECT c.id,c.email,c.email_type,c.verified_at,s.full_name,o.name AS organisation FROM staff_email_contacts c JOIN staff_profiles s ON s.staff_identity_id=c.staff_identity_id LEFT JOIN organisations o ON o.id=s.organisation_id WHERE '.$where.' ORDER BY c.id DESC LIMIT 25 OFFSET '.(($page-1)*25),$args)->fetchAll();$e=fn($v)=>Support::escape((string)$v);
