   [$scope,$args]=Authorization::scope($p,$actor,'core.staff.professional.verify','r.organisation_id');$rows=Database::query($p,'SELECT r.*,s.full_name FROM staff_profile_reviews r JOIN staff_profiles s ON s.staff_identity_id=r.staff_identity_id WHERE '.$scope.' ORDER BY r.id DESC LIMIT 100',$args)->fetchAll();$h.='<h3>Professional requests</h3>';foreach($rows as $r){$h.='<article class="registration-row"><h4>'.$e($r['full_name'].' · '.$r['status']).'</h4>'.self::professionalSummary($p,json_decode($r['proposed_json'],true)).'<a href="/download?id='.(int)$r['evidence_document_id'].'&amp;version='.(int)$r['evidence_version'].'">Semak bukti dokumen #'.(int)$r['evidence_document_id'].'</a>';if($r['status']==='PENDING_VERIFICATION')$h.=Support::form('professional_review','<input type="hidden" name="review_id" value="'.(int)$r['id'].'">'.self::select('decision','Keputusan',[['id'=>'VERIFIED','name'=>'Verified'],['id'=>'REJECTED','name'=>'Reject']]).Support::fields(['reason'=>['Sebab / bukti disemak','text','']]),'Sahkan keputusan');$h.='</article>';}
   [$scope,$args]=Authorization::scope($p,$actor,'core.registrations.review','s.organisation_id');$contacts=Database::query($p,'SELECT c.id,c.email,c.email_type,c.status,s.full_name FROM staff_email_contacts c JOIN staff_profiles s ON s.staff_identity_id=c.staff_identity_id WHERE '.$scope.' ORDER BY c.id DESC LIMIT 100',$args)->fetchAll();$h.='<h3>Alternative/official email approval</h3>';foreach($contacts as $c){$h.='<article class="registration-row"><p>'.$e($c['full_name'].' · '.$c['email'].' · '.$c['status']).'</p>';if($c['status']==='PENDING_ADMIN_APPROVAL')$h.=Support::form('contact_review','<input type="hidden" name="contact_id" value="'.(int)$c['id'].'">'.self::select('decision','Keputusan',[['id'=>'APPROVED','name'=>'Approve identity'],['id'=>'REJECTED','name'=>'Reject']]).Support::fields(['reason'=>['Sebab / bukti identiti','text','']]),'Review email');$h.='</article>';}return $h.'</section>';
  }
  if($tab==='catalog'){Authorization::require($p,$actor,'core.master.manage');$h.=SpecialistCatalog::panel($p,$actor);$rows=Database::query($p,'SELECT id,name,category,verification_status,is_active,source_reference FROM professional_master_catalog ORDER BY category,name')->fetchAll();$h.=self::smartTable($rows);$batch='';foreach(MasterSourceImport::candidates()['professional_addenda_candidates']??[] as $candidate)if($candidate['verification_status']==='VERIFIED')$batch.='<label><input type="checkbox" name="catalog_codes[]" value="'.$e($candidate['code']).'">'.$e($candidate['name']).' (nomenclature only; appointment evidence required)</label>';$h.=Support::form('professional_catalog_import',$batch.Support::fields(['reason'=>['Sebab kelulusan batch','text','']]),'Import selected VERIFIED catalog');$f=self::select('category','Kategori',array_map(fn($x)=>['id'=>$x,'name'=>$x],['speciality','subspeciality','administrative_position','top_grade','unit_template'])).Support::fields(['code'=>['Kod dalaman unik','text',''],'name'=>['Nama rasmi','text',''],'source'=>['Rujukan rasmi HTTPS','url',''],'reason'=>['Bukti / sebab','text','']]).self::select('profession_id','Profesion berkaitan',RegistrationMaster::masters($p,'profession')).self::select('parent_id','Kepakaran induk',Database::query($p,"SELECT id,name FROM professional_master_catalog WHERE category='speciality' AND is_active=1 AND verification_status='VERIFIED' ORDER BY name")->fetchAll()).self::select('is_active','Status',[['id'=>'1','name'=>'Aktif'],['id'=>'0','name'=>'Inactive']]);$h.=Support::form('professional_catalog',$f,'Verify/save catalog');return $h.'</section>';}
  if($tab==='facility_review'){if(!Authorization::any($p,$actor,'core.organisations.manage')&&!Authorization::allowed($p,$actor,'core.master.manage'))throw new \RuntimeException('Akses directory diperlukan.');$h.='<p>Lokasi geografi bukan bukti administrative parent. VERIFIED memerlukan bukti/source yang disemak Admin. HOLD/INVALID tidak boleh diimport.</p>'.Support::form('facility_review',Support::fields(['local_code'=>['Kod calon katalog','text',''],'source'=>['URL bukti induk rasmi','url',''],'reason'=>['Hasil semakan','text','']]).self::select('parent_id','Induk pentadbiran sebenar',$orgs).self::select('verification_status','Status',array_map(fn($s)=>['id'=>$s,'name'=>$s],['VERIFIED','PARTIAL','HOLD','INCOMPLETE','INVALID'])),'Rekod semakan');$h.='<h3>Verified organisation address/contact</h3>'.Support::form('directory_verify','<input type="hidden" name="expected_hash" value="">'.self::select('organisation_id','Organisasi sedia ada',$orgs).self::optionalFields(['address'=>'Alamat rasmi penuh (kosong jika tidak diketahui)','postcode'=>'Poskod','city'=>'Bandar','street'=>'Jalan / taman','address_state'=>'Negeri alamat','district'=>'Daerah geografi','phone'=>'Telefon rasmi (pilihan)']).Support::fields(['source'=>['Sumber rasmi HTTPS','url',''],'reason'=>['Bukti / sebab kemas kini','text','']]),'Sahkan directory — overwrite hanya selepas approval').'<p>Medan kosong direkod sebagai NULL. Semak nilai sebelum submit; ID, kod dan hierarchy tidak berubah.</p>';$h.=self::smartTable(Database::query($p,'SELECT local_code,parent_id,verification_status,source_reference,reviewed_at FROM organisation_source_reviews ORDER BY local_code')->fetchAll());$previews=[];foreach(Database::query($p,'SELECT o.id,o.name,o.address,o.phone,d.postcode,d.city,d.street,d.address_state,d.district,d.source_reference,d.verification_status FROM organisations o LEFT JOIN organisation_directory_details d ON d.organisation_id=o.id')->fetchAll() as $o){$o['expected_hash']=hash('sha256',json_encode(array_diff_key($o,['name'=>true]),JSON_THROW_ON_ERROR));$previews[]=$o;}$h.='<script type="application/json" id="directory-edit-data">'.json_encode($previews,JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_THROW_ON_ERROR).'</script>';return $h.'</section>';}
