  if($tab==='official_names'){$h.='<p>Nama asal disimpan sebagai alias; ID/kod/parent/RBAC tidak berubah. Tiada penyeragaman automatik tanpa pengesahan Admin.</p>'.Support::form('official_name',self::select('organisation_id','Organisasi',$orgs).Support::fields(['official_name'=>['Nama rasmi penuh','text',''],'source'=>['Sumber rasmi HTTPS','url',''],'reason'=>['Sebab / bukti','text','']]),'Sahkan nama rasmi');return $h.'</section>';}
  throw new \InvalidArgumentException('Tab tidak sah.');
 }
 private static function smartTable(array $rows):string {if(!$rows)return '<p>Tiada rekod.</p>';$columns=array_keys($rows[0]);$h='<div class="table-wrap addenda-smart-table"><table><thead><tr>';foreach($columns as $key)$h.='<th>'.Support::escape($key).'</th>';$h.='</tr></thead><tbody>';foreach($rows as $r){$h.='<tr>';foreach($columns as $key)$h.='<td>'.Support::escape((string)($r[$key]??'')).'</td>';$h.='</tr>';}$h.='</tbody></table></div>';return $h;}

 public static function addendaAction(\PDO $p,int $actor,string $action,array $d):void {
  switch($action){
   case 'directory_verify':RegistrationMaster::verifyDirectory($p,$actor,Core::id($d['organisation_id']??null),$d);break;
   case 'professional_catalog_import':$selected=$d['catalog_codes']??[];if(!is_array($selected))throw new \InvalidArgumentException('Pilihan tidak sah.');MasterSourceImport::importProfessionalCatalog($p,$actor,$selected,Core::text($d['reason']??'',500));break;
   case 'professional_review':RegistrationMaster::reviewProfessional($p,$actor,Core::id($d['review_id']??null),Core::text($d['decision']??'',30),Core::text($d['reason']??'',500));break;
   case 'specialist_catalog_activate':SpecialistCatalog::activate($p,$actor,Core::text($d['reason']??'',500));break;
   case 'contact_review':RegistrationMaster::emailContactReview($p,$actor,Core::id($d['contact_id']??null),Core::text($d['decision']??'',30),Core::text($d['reason']??'',500));break;
   case 'professional_catalog':RegistrationMaster::professionalCatalogSave($p,$actor,$d);break;
   case 'facility_review':MasterSourceImport::reviewOrganisationSource($p,$actor,Core::text($d['local_code']??'',64),Core::id($d['parent_id']??null),Core::text($d['verification_status']??'',20),Core::text($d['source']??'',1000),Core::text($d['reason']??'',500));break;
   case 'unit_save':MasterSourceImport::unitSave($p,$actor,$d,Core::id($d['unit_id']??null,true));break;
   case 'official_name':MasterSourceImport::organisationOfficialName($p,$actor,Core::id($d['organisation_id']??null),Core::text($d['official_name']??''),Core::text($d['source']??'',1000),Core::text($d['reason']??'',500));break;
   default:throw new \InvalidArgumentException('Tindakan tidak sah.');
  }
 }
 private static function aliases(\PDO $p,array $rows):array {if(!RegistrationMaster::profileReady($p))return $rows;$aliases=[];foreach(Database::query($p,'SELECT organisation_id,alias FROM organisation_search_aliases')->fetchAll() as $a)$aliases[$a['organisation_id']][]=$a['alias'];foreach($rows as &$r){$r['aliases']=$aliases[$r['id']]??[];$original=$r['name'];$r['name']=FacilityDirectory::fullName($original);if($r['name']!==$original)$r['aliases'][]=$original;}unset($r);return $rows;}
 private static function professionalSummary(\PDO $p,array $values):string {$labels=['profession_id'=>'Profesion','position_id'=>'Skim','grade_id'=>'Gred hakiki','speciality_id'=>'Kepakaran','subspeciality_id'=>'Subkepakaran','administrative_position_id'=>'Jawatan pentadbiran','top_grade_id'=>'Gred pengurusan tertinggi','substantive_position'=>'Jawatan hakiki','acting_grade'=>'Memangku','kup_grade'=>'KUP','specialist_level'=>'Tahap kepakaran'];$h='<dl>';foreach($labels as $key=>$label){$v=$values[$key]??null;if(str_ends_with($key,'_id')&&$v){$table=in_array($key,['profession_id','position_id','grade_id'],true)?'master_data':'professional_master_catalog';$v=Database::query($p,'SELECT name FROM '.$table.' WHERE id=?',[$v])->fetchColumn();}$h.='<dt>'.Support::escape($label).'</dt><dd>'.Support::escape((string)($v?:'—')).'</dd>';}return $h.'</dl>';}
 private static function optionalFields(array $fields,string $type='text'):string {$h='';foreach($fields as $name=>$label)$h.='<label>'.Support::escape($label).'<input name="'.Support::escape($name).'" type="'.Support::escape($type).'" maxlength="190"></label>';return $h;}
}